import { Project } from '../../src'
import { RelationshipResolver } from '../../src/orchestrator/dependencies'
import { Plugin } from '@servicenow/sdk-build-core'

describe('Relationship Generator', () => {
    test('resolves relationships for a table', async () => {
        const project = new Project()
        const resolver = new RelationshipResolver(project)
        const expectedHierarchies = [
            {
                sys_script_client: {
                    nodeId: 'node1',
                    table: 'sys_script_client',
                    composite: false,
                },
            },
        ]
        const hierarchies = resolver.resolveRelationship('sys_script_client')
        expect(hierarchies).toEqual(expectedHierarchies)
    })

    test('Captures composite flag in plugin relationships', async () => {
        const project = new Project()
        const resolver = new RelationshipResolver(project)
        const expectedHierarchies = [
            {
                sys_ui_list: {
                    nodeId: 'node1',
                    table: 'sys_ui_list',
                    composite: true, //sets to true since list xml composes all elements as children
                    relationships: {
                        sys_ui_list_element: {
                            nodeId: 'node2',
                            table: 'sys_ui_list_element',
                            via: {
                                type: 'string',
                                value: 'list_id',
                            },
                            inverse: false,
                            composite: false,
                        },
                    },
                },
            },
        ]
        const hierarchies = resolver.resolveRelationship('sys_ui_list')
        expect(hierarchies).toEqual(expectedHierarchies)
    })

    test('Filters out relationships withunsupported via syntax', async () => {
        const plugin = Plugin.create({
            name: 'Test1Plugin',
            records: {
                parent_one: {
                    relationships: {
                        child_one: {
                            via: 1 as any,
                            descendant: true,
                        },
                    },
                },
            },
        })
        const plugin2 = Plugin.create({
            name: 'Test2Plugin',
            records: {
                another_parent: {
                    relationships: {
                        child_one: {
                            via: '1',
                            descendant: true,
                        },
                    },
                },
            },
        })
        const project = new Project()
        project.getPlugins().append(plugin)
        project.getPlugins().append(plugin2)
        const resolver = new RelationshipResolver(project)
        const hierarchies = resolver.resolveRelationship('child_one')
        const expectedHierarchies = [
            {
                another_parent: {
                    nodeId: 'node3',
                    table: 'another_parent',
                    composite: false,
                    relationships: {
                        child_one: {
                            nodeId: 'node4',
                            table: 'child_one',
                            via: {
                                type: 'string',
                                value: '1',
                            },
                            inverse: false,
                            composite: false,
                        },
                    },
                },
            },
        ]
        expect(hierarchies).toEqual(expectedHierarchies)
    })

    test('Handles cyclic relationships', async () => {
        const plugin = Plugin.create({
            name: 'TestPlugin',
            records: {
                parent_one: {
                    relationships: {
                        child_one: {
                            via: 'name',
                            descendant: true,
                        },
                    },
                },
                child_one: {
                    relationships: {
                        child_one: {
                            via: 'parent_id',
                            descendant: true,
                        },
                    },
                },
            },
        })
        const project = new Project()
        project.getPlugins().append(plugin)
        const resolver = new RelationshipResolver(project)
        const hierarchies = resolver.resolveRelationship('parent_one')
        const expectedHierarchies = [
            {
                parent_one: {
                    nodeId: 'node1',
                    table: 'parent_one',
                    composite: false,
                    relationships: {
                        child_one: {
                            nodeId: 'node2',
                            table: 'child_one',
                            via: {
                                type: 'string',
                                value: 'name',
                            },
                            inverse: false,
                            composite: false,
                            relationships: {
                                child_one: {
                                    nodeId: 'node3',
                                    table: 'child_one',
                                    via: {
                                        type: 'string',
                                        value: 'parent_id',
                                    },
                                    inverse: false,
                                    composite: false,
                                    cycleTargetNodeId: 'node2',
                                },
                            },
                            cyclicReferences: ['node3'],
                        },
                    },
                },
            },
        ]
        expect(hierarchies).toEqual(expectedHierarchies)
    })
})
